ew data-v-61b9cd59="" class="form-card select-card"><uni-view data-v-61b9cd59="" class="card-head"><uni-text data-v-61b9cd59="" class="card-label"><span>选择售出编号</span></uni-text><uni-view data-v-61b9cd59="" class="card-head-meta"><uni-text data-v-61b9cd59="" class="meta-tip"><span>可出售数量：</span></uni-text><uni-view data-v-61b9cd59="" class="meta-tip-row"><uni-text class="meta-tip"><span>拥有数量：{{ g.circ }}</span></uni-text><uni-text class="meta-tip"><span>已选择：{{ qty }}</span></uni-text></uni-view></uni-view></uni-view><uni-view data-v-61b9cd59="" class="select-empty"><uni-text data-v-61b9cd59="" class="select-empty-text"><span>选择要出售的数字版权品</span></uni-text></uni-view></uni-view><uni-view data-v-61b9cd59="" class="form-card pay-card"><uni-view data-v-61b9cd59="" class="card-label">支付方式</uni-view><uni-view class="pay-row" @click="payIdx = (payIdx + 1) % pays.length"><uni-view class="pay-name">{{ pays[payIdx] }}</uni-view><uni-text data-v-61b9cd59="" class="cuIcon-roundcheckfill pay-check"><span></span></uni-text></uni-view></uni-view><uni-view data-v-61b9cd59="" class="form-card income-card"><uni-view data-v-61b9cd59="" class="card-label">预计收入</uni-view><uni-view data-v-61b9cd59="" class="income-row"><uni-view data-v-61b9cd59="" class="income-label-wrap"><uni-text data-v-61b9cd59="" class="income-label"><span>总售价</span></uni-text><uni-text data-v-61b9cd59="" class="income-sub"><span>(单价 * 数量)</span></uni-text></uni-view><uni-text class="income-value"><span>￥{{ price }}x{{ qty }} = ￥{{ subtotal }}</span></uni-text></uni-view><uni-view data-v-61b9cd59="" class="income-row"><uni-view data-v-61b9cd59="" class="income-label-wrap"><uni-text data-v-61b9cd59="" class="income-label"><span>综合服务费</span></uni-text><uni-text data-v-61b9cd59="" class="income-sub"><span>(5%)</span></uni-text></uni-view><uni-text class="income-value income-minus"><span>-￥{{ fee }}</span></uni-text></uni-view><uni-view data-v-61b9cd59="" class="income-row income-row-total"><uni-text data-v-61b9cd59="" class="income-label"><span>预计收入</span></uni-text><uni-text class="income-value income-total"><span>￥{{ total }}</span></uni-text></uni-view></uni-view><uni-view data-v-61b9cd59="" class="form-card agree-card"><uni-view data-v-61b9cd59="" class="card-label">服务须知</uni-view><uni-view data-v-61b9cd59="" class="agree-row"><uni-text data-v-61b9cd59="" class="cuIcon-roundcheckfill agree-check"><span></span></uni-text><uni-text data-v-61b9cd59="" class="agree-text"><span>我已同意</span></uni-text><uni-text data-v-61b9cd59="" class="agree-link"><span>《服务协议》</span></uni-text></uni-view></uni-view><uni-view data-v-61b9cd59="" class="form-card tip-card"><uni-view data-v-61b9cd59="" class="card-label">以求购价出售说明</uni-view><uni-view data-v-61b9cd59="" class="tip-content"><uni-text data-v-61b9cd59="" class="tip-line"><span>1.系统将按照买方求购订单价格成交。</span></uni-text><uni-text data-v-61b9cd59="" class="tip-line"><span>2.买方求购订单付款钱包需与卖方选择的收款钱包保持一致，钱包不匹配将无法成交。</span></uni-text><uni-text data-v-61b9cd59="" class="tip-line"><span>3.交易成功后订单立即生效，成交后不支持撤销、回滚，请确认后再提交出售。</span></uni-text></uni-view></uni-view></uni-view><uni-view data-v-61b9cd59="" class="bottom-bar"><uni-view data-v-61b9cd59="" class="bottom-left"><uni-view class="bottom-price">￥{{ total }}</uni-view><uni-view data-v-61b9cd59="" class="bottom-label">预计收入</uni-view></uni-view><uni-view class="buy-btn" @click="submit">确认出售</uni-view></uni-view><uni-view data-v-61b9cd59="" class="cu-modal pick-modal"><uni-view data-v-61b9cd59="" class="cu-dialog pick-dialog"><uni-view data-v-61b9cd59="" class="pick-header"><uni-text data-v-61b9cd59="" class="pick-title"><span>请选择一个数字版权品</span></uni-text><uni-text data-v-61b9cd59="" class="pick-subtitle"><span>已选 0 / 0</span></uni-text></uni-view><uni-scroll-view data-v-61b9cd59="" class="pick-scroll"><div class="uni-scroll-view"><div class="uni-scroll-view" style="overflow: hidden auto;"><div class="uni-scroll-view-content"><uni-view data-v-61b9cd59="" class="pick-grid"></uni-view></div></div></div></uni-scroll-view><uni-view data-v-61b9cd59="" class="pick-footer"><uni-view data-v-61b9cd59="" class="pick-done-btn">完成</uni-view></uni-view></uni-view></uni-view></uni-view>
</template>

<script setup>
import { ref, computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { getGoods } from '@/mock/goods'
import { toast, isLogin } from '@/utils/interact'

const route = useRoute()
const router = useRouter()

const g = getGoods(route.query.id)
const qty = ref(1)
const price = ref(g.floor || 10)
const payIdx = ref(0)
const pays = ['汇付', '微信支付', '支付宝']

const subtotal = computed(() => (price.value * qty.value).toFixed(2))
const fee = computed(() => (price.value * qty.value * 0.05).toFixed(2))
const total = computed(() => (price.value * qty.value * 0.95).toFixed(2))

function submit() {
  if (!isLogin()) return toast('请先登录')
  if (qty.value < 1) return toast('出售数量至少 1 份')
  toast(`已提交出售：${g.name} ×${qty.value}，预计收入 ¥${total.value}`)
  setTimeout(() => router.back(), 1200)
}
</script>
